@Delete('/sessions/:id')
  @Header('Cache-Control', 'no-store')
  @Header('Pragma', 'no-cache')
  async revokeAuthSession(
    @Req() req: Request,
    @CurrentUser() user: CurrentUser,
    @Session() session: Session | AuthSessionPrincipal | undefined,
    @Param('id') authSessionId: string
  ) {
    const parsedSessionId = SessionIdSchema.safeParse(authSessionId);
    if (!parsedSessionId.success) throw new InvalidAuthState();
    this.assertSessionMutationAuthorized(req, session);
    await this.authSessions.revoke(
      parsedSessionId.data,
      'user_action',
      user.id
    );
    return {};
  }

@Get('/')
  @Delete('/')
  @Public()
  @HttpCode(HttpStatus.METHOD_NOT_ALLOWED)
  async STATELESS_MCP_ENDPOINT() {
    return this.errorResponse(null, -32000, 'Method not allowed.');
  }

@Public()
  @Get('/captcha')
  @Header('Cache-Control', 'no-store')
  async getChallenge(@Req() req: Request) {
    return this.captcha.getClientConfig(
      req.get('x-affine-client-kind') === 'native'
    );
  }

@UseNamedGuard('version')
  @Get('/methods')
  async boundMethods(@CurrentUser() user: CurrentUser) {
    return this.runtime.executeAuthSessionCommandV1({
      action: 'bound_methods',
      userId: user.id,
    });
  }

@UseNamedGuard('version')
  @Throttle('default', { limit: 1200 })
  @Public()
  @Get('/session')
  @Header('Cache-Control', 'no-store')
  async currentSessionUser(@CurrentUser() user?: CurrentUser) {
    return { user };
  }

@Get('/sessions')
  @Header('Cache-Control', 'no-store')
  @Header('Pragma', 'no-cache')
  async listAuthSessions(
    @CurrentUser() user: CurrentUser,
    @Session() session: Session | AuthSessionPrincipal | undefined
  ) {
    const currentId = (session as Partial<AuthSessionPrincipal> | undefined)
      ?.authSessionId;
    return (await this.authSessions.list(user.id)).map(item => ({
      ...item,
      current: item.id === currentId,
    }));
  }

@Get('/:id')
  async getAvatar(@Res() res: Response, @Param('id') id: string) {
    if (!this.storage.isLocalStorage()) {
      throw new ActionForbidden(
        'Only available when avatar storage provider is fs or assetpack.'
      );
    }

    const { body, metadata } = await this.storage.get(id);

    if (!body) {
      throw new UserAvatarNotFound();
    }

    // metadata should always exists if body is not null
    if (metadata) {
      res.setHeader('content-type', metadata.contentType);
      res.setHeader('last-modified', metadata.lastModified.toISOString());
      res.setHeader('content-length', metadata.contentLength);
    }
    applyAttachHeaders(res, {
      contentType: metadata?.contentType,
      filename: `${id}`,
    });

    body.pipe(res);
  }

@Public()
  @Get('/oauth/callback')
  @HttpCode(HttpStatus.OK)
  async callbackGet(
    @Res() res: Response,
    @Query('code') code?: string,
    @Query('state') stateStr?: string
  ) {
    return this.handleCallback(res, code, stateStr);
  }

@Sse('/actions/:sessionId/stream')
  @CallMetric('ai', 'action_stream', { timer: true })
  async actionStream(
    @CurrentUser() user: CurrentUser,
    @Req() req: Request,
    @Param('sessionId') sessionId: string,
    @Query() query: Record<string, string>
  ): Promise<Observable<ChatEvent>> {
    try {
      const { signal } = getSignal(req);

