@Post('/collect')
  async collect(
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
    @Body() batch: TelemetryBatch,
    @CurrentUser() user?: CurrentUserType
  ): Promise<TelemetryAck> {
    const origin = req.headers.origin;
    const referer = req.headers.referer;
    if (!this.telemetry.isOriginAllowed(origin, referer)) {
      throw new BadRequest('Invalid origin: ' + origin);
    }

    res.header({
      ...this.telemetry.getCorsHeaders(origin),
    });

    const patchedBatch =
      user && Array.isArray(batch?.events)
        ? {
            ...batch,
            events: batch.events.map(event => ({
              ...event,
              userId: event.userId ?? user.id,
            })),
          }
        : batch;

    return this.telemetry.collectBatch(patchedBatch);
  }

@Post('/link-preview')
  async linkPreview(
    @Req() request: ExpressRequest,
    @Res() resp: ExpressResponse
  ): Promise<ExpressResponse> {
    const origin = request.headers.origin;
    const referer = request.headers.referer;
    const originAllowed = origin
      ? isOriginAllowed(origin, this.allowedOrigin)
      : false;
    const refererAllowed = referer
      ? isRefererAllowed(referer, this.allowedOrigin)
      : false;
    if (!originAllowed && !refererAllowed) {
      this.logger.error('Invalid Origin', {
        origin: safeLogUrl(origin),
        referer: safeLogUrl(referer),
      });
      throw new BadRequest('Invalid header');
    }

    const logOrigin = safeLogUrl(origin);
    this.logger.debug('Received request', {
      origin: logOrigin,
      method: request.method,
    });

    const requestBody = parseJson<LinkPreviewRequest>(request.body);
    const targetURL = fixUrl(requestBody?.url);
    // not allow same site preview
    if (!targetURL || isOriginAllowed(targetURL.origin, this.allowedOrigin)) {
      this.logger.error('Invalid URL', {
        origin: logOrigin,
        url: safeLogUrl(requestBody?.url),
      });
      throw new BadRequest('Invalid URL');
    }

    const logUrl = safeLogUrl(targetURL);
    this.logger.debug('Processing request', { origin: logOrigin, url: logUrl });

    try {
      const cachedUrl = `link-preview:${targetURL.toString()}`;
      const cachedResponse = await this.cache.get<string>(cachedUrl);
      if (cachedResponse) {
        return resp
          .status(200)
          .header({
            'content-type': 'application/json;charset=UTF-8',
            ...getCorsHeaders(origin),
          })
          .send(cachedResponse);
      }

      const method: 'GET' | 'HEAD' = requestBody?.head ? 'HEAD' : 'GET';

      const response = await safeFetch(
        targetURL.toString(),
        { method, headers: cloneHeader(request.headers) },
        {
          timeoutMs: FETCH_TIMEOUT_MS,
          maxRedirects: MAX_REDIRECTS,
          maxBytes: LINK_PREVIEW_MAX_BYTES,
        }
      );
      this.logger.debug('Fetched URL', {
        origin: logOrigin,
        url: logUrl,
        status: response.status,
      });

      if (requestBody?.head) {
        return resp
          .status(
            response.status >= 200 && response.status < 400
              ? 204
              : response.status
          )
          .header(getCorsHeaders(origin))
          .send();
      }

      const res: LinkPreviewResponse = {
        url: response.url,
        images: [],
        videos: [],
        favicons: [],
      };

      if (response.body) {
        const body = Buffer.from(await response.arrayBuffer());
        const limitedResponse = new Response(body, response);
        const resp = await decodeWithCharset(limitedResponse, res);

        const rewriter = new HTMLRewriter()
          .on('meta', {
            element(element) {
              const property =
                element.getAttribute('property') ??
                element.getAttribute('name');
              const content = element.getAttribute('content');
              if (property && content) {
                switch (property.toLowerCase()) {
                  case 'og:title':
                    res.title = content;
                    break;
                  case 'og:site_name':
                    res.siteName = content;
                    break;
                  case 'og:description':
                    res.description = content;
                    break;
                  case 'og:image':
                    appendUrl(content, res.images);
                    break;
                  case 'og:video':
                    appendUrl(content, res.videos);
                    break;
                  case 'og:type':
                    res.mediaType = content;
                    break;
                  case 'description':
                    if (!res.description) {
                      res.description = content;
                    }
                }
              }
            },
          })
          .on('link', {
            element(element) {
              if (element.getAttribute('rel')?.toLowerCase().includes('icon')) {
                appendUrl(element.getAttribute('href'), res.favicons);
              }
            },
          })
          .on('title', {
            text(text) {
              if (!res.title) {
                res.title = text.text;
              }
            },
          })
          .on('img', {
            element(element) {
              appendUrl(element.getAttribute('src'), res.images);
            },
          })
          .on('video', {
            element(element) {
              appendUrl(element.getAttribute('src'), res.videos);
            },
          });

        await rewriter.transform(resp).text();

        res.images = await reduceUrls(res.images);

        this.logger.debug('Processed response with HTMLRewriter', {
          origin: logOrigin,
          url: safeLogUrl(response.url),
        });
      }

      // fix favicon
      {
        // head default path of favicon
        const faviconUrl = new URL('/favicon.ico?v=2', response.url);
        const faviconResponse = await safeFetch(
          faviconUrl.toString(),
          { method: 'HEAD' },
          {
            timeoutMs: FETCH_TIMEOUT_MS,
            maxRedirects: MAX_REDIRECTS,
            maxBytes: 0,
          }
        );
        if (faviconResponse.ok) {
          appendUrl(faviconUrl.toString(), res.favicons);
        }

        res.favicons = await reduceUrls(res.favicons);
      }

      const json = JSON.stringify(res);
      this.logger.debug('Sending response', {
        origin: logOrigin,
        url: safeLogUrl(res.url),
        responseSize: json.length,
      });

      await this.cache.set(cachedUrl, res, { ttl: CACHE_TTL });
      return resp
        .status(200)
        .header({
          'content-type': 'application/json;charset=UTF-8',
          ...getCorsHeaders(origin),
        })
        .send(json);
    } catch (error) {
      if (error instanceof SsrfBlockedError) {
        const reason = error.data?.reason as SSRFBlockReason | undefined;
        this.logger.warn('Blocked link preview target', {
          origin: logOrigin,
          url: safeLogUrl(requestBody?.url),
          reason,
        });
        throw new BadRequest(toBadRequestReason(reason ?? 'invalid_url'));
      }
      if (error instanceof ResponseTooLargeError) {
        this.logger.warn('Link preview response too large', {
          origin: logOrigin,
          url: safeLogUrl(requestBody?.url),
          limitBytes: error.data?.limitBytes,
          receivedBytes: error.data?.receivedBytes,
        });
        throw new BadRequest('Response too large');
      }
      this.logger.error('Error fetching URL', {
        origin: logOrigin,
        url: logUrl,
        error: safeLogError(error),
      });
      throw new BadRequest('Error fetching URL');
    }
  }

@Public()
  @Post(['/api/stripe/webhook', '/api/worker/stripeWebhook'])
  async handleWebhook(@Req() req: RawBodyRequest<Request>) {
    const signature = req.headers['stripe-signature'];
    try {
      return await this.runtime.capturePaymentWebhookV1(
        'stripe',
        Buffer.from(req.rawBody ?? ''),
        typeof signature === 'string' ? signature : ''
      );
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (message.includes('invalid Stripe webhook signature')) {
        throw new BadRequest(message);
      }
      throw new InternalServerError(message);
    }
  }

@Throttle('default')
  @Public()
  @Post('/')
  async mcp(
    @Req() req: Request,
    @Res() res: Response,
    @Param('workspaceId') workspaceId: string
  ) {
    const abortController = new AbortController();
    req.on('close', () => abortController.abort());

    try {
      const token =
        extractTokenFromHeader(req.get('authorization') ?? '') ?? '';
      const credential = await this.credentials.authenticate(
        token,
        workspaceId
      );
      const server = await this.provider.for(
        credential.userId,
        workspaceId,
        credential.accessMode
      );
      const body = req.body as unknown;
      const isBatch = Array.isArray(body);
      const messages = isBatch ? body : [body];

      if (!messages.length) {
        res
          .status(HttpStatus.BAD_REQUEST)
          .json(this.errorResponse(null, -32600, 'Invalid Request'));
        return;
      }
      if (messages.length > MAX_BATCH_SIZE) {
        res
          .status(HttpStatus.BAD_REQUEST)
          .json(
            this.errorResponse(
              null,
              -32600,
              `Batch size exceeds limit (${MAX_BATCH_SIZE}).`
            )
          );
        return;
      }

      const responses: JsonRpcResponse[] = [];
      for (const message of messages) {
        const response = await this.handleMessage(
          message,
          server,
          abortController.signal
        );
        if (response) {
          responses.push(response);
        }
      }

      if (!responses.length) {
        res.status(HttpStatus.ACCEPTED).send();
        return;
      }

      res.status(HttpStatus.OK).json(isBatch ? responses : responses[0]);
    } catch (error) {
      if (error instanceof HttpException) {
        res
          .status(error.getStatus())
          .json(this.errorResponse(null, -32000, 'Authentication failed'));
        return;
      }
      if (error instanceof ActionForbidden) {
        res
          .status(HttpStatus.FORBIDDEN)
          .json(this.errorResponse(null, -32000, 'Access denied'));
        return;
      }
      this.logger.error('Failed to handle MCP request', error);
      res
        .status(HttpStatus.INTERNAL_SERVER_ERROR)
        .json(this.errorResponse(null, -32603, 'Internal error'));
    }
  }

@Put('/chat/:sessionId/attachments/:key')
  @CallMetric('ai', 'session_attachment_upload')
  async upload(
    @CurrentUser() user: CurrentUser,
    @Param('sessionId') sessionId: string,
    @Param('key') key: string,
    @Query('workspaceId') workspaceId: string,
    @Query('mimeType') declaredMimeType: string | undefined,
    @Query('fileName') fileName: string | undefined,
    @Req() req: RawBodyRequest<Request>
  ) {
    await this.assertCanonicalSession(user.id, sessionId, workspaceId);
    const buffer = req.rawBody;
    if (!buffer?.length) {
      throw new BadRequest('Copilot attachment body is required');
    }
    const expectedKey = createHash('sha256').update(buffer).digest('base64url');
    if (key !== expectedKey) {
      throw new BadRequest('Copilot attachment checksum mismatch');
    }
    await this.storage.handleUploadBuffer(buffer);
    await this.assertCanonicalSession(user.id, sessionId, workspaceId);
    const mimeType = sniffMime(buffer, declaredMimeType)?.toLowerCase();
    await this.storage.putSessionAttachment(
      user.id,
      workspaceId,
      key,
      buffer,
      mimeType || 'application/octet-stream'
    );
    return {
      url: this.storage.sessionAttachmentUrl(
        sessionId,
        workspaceId,
        key,
        fileName
      ),
    };
  }

@Public()
  @Put('multipart')
  @CallMetric('controllers', 'r2_proxy_multipart')
  async uploadPart(@Req() req: Request, @Res() res: Response) {
    this.ensureUploadProxyEnabled();

    const workspaceId = this.expectString(req.query.workspaceId, 'workspaceId');
    const key = this.expectString(req.query.key, 'key');
    const uploadId = this.expectString(req.query.uploadId, 'uploadId');
    const token = this.expectString(req.query.token, 'token');
    const expiresAt = this.number(req.query.expiresAt, 'expiresAt');
    const partNumber = this.number(req.query.partNumber, 'partNumber');
    const contentLengthFromQuery = this.number(
      req.query.contentLength,
      'contentLength'
    );

    if (partNumber < 1) {
      throw new BlobInvalid('Invalid part number');
    }
    if (
      !Number.isInteger(contentLengthFromQuery) ||
      contentLengthFromQuery < 1
    ) {
      throw new BlobInvalid('Invalid content length');
    }

    this.ensureNotExpired(expiresAt);

    if (
      !this.rt.verifyUploadToken(
        'blob',
        PROXY_MULTIPART_PATH,
        [workspaceId, key, uploadId, partNumber, contentLengthFromQuery],
        expiresAt,
        token
      )
    ) {
      throw new BlobInvalid('Invalid upload token');
    }

    const record = await this.models.blob.get(workspaceId, key);
    if (!record) {
      throw new BlobInvalid('Multipart upload is not initialized');
    }
    if (record.status === 'completed' || record.deletedAt) {
      throw new BlobInvalid('Blob upload is already completed');
    }
    if (record.uploadId !== uploadId) {
      throw new BlobInvalid('Upload id mismatch');
    }

    const contentLength = this.parseContentLength(req);
    if (contentLength === undefined || contentLength === 0) {
      throw new BlobInvalid('Missing Content-Length header');
    }
    if (contentLength !== contentLengthFromQuery) {
      throw new BlobInvalid('Content length mismatch');
    }

    const maxPartNumber = Math.ceil(record.size / MULTIPART_PART_SIZE);
    if (partNumber > maxPartNumber) {
      throw new BlobInvalid('Part number exceeds upload size');
    }
    if (
      record.size &&
      (partNumber - 1) * MULTIPART_PART_SIZE + contentLength > record.size
    ) {
      throw new BlobInvalid('Part size exceeds upload metadata');
    }

    try {
      const etag = await this.rt.proxyUploadPart(
        'blob',
        `${workspaceId}/.reservations/${record.reservationId}/${key}`,
        uploadId,
        partNumber,
        await toBuffer(req),
        contentLength
      );
      if (etag) {
        res.setHeader('etag', etag);
      }
    } catch (error) {
      this.logger.error('Failed to proxy multipart upload', error as Error);
      throw new BlobInvalid('Upload failed');
    }

    res.status(200).end();
  }

@Public()
  @Put('upload')
  @CallMetric('controllers', 'r2_proxy_upload')
  async upload(@Req() req: Request, @Res() res: Response) {
    this.ensureUploadProxyEnabled();

    const workspaceId = this.expectString(req.query.workspaceId, 'workspaceId');
    const key = this.expectString(req.query.key, 'key');
    const token = this.expectString(req.query.token, 'token');
    const expiresAt = this.number(req.query.expiresAt, 'expiresAt');
    const contentType = this.expectString(req.query.contentType, 'contentType');
    const contentLengthFromQuery = this.number(
      req.query.contentLength,
      'contentLength'
    );
    if (
      !Number.isInteger(contentLengthFromQuery) ||
      contentLengthFromQuery < 0
    ) {
      throw new BlobInvalid('Invalid content length');
    }

    this.ensureNotExpired(expiresAt);

    if (
      !this.rt.verifyUploadToken(
        'blob',
        PROXY_UPLOAD_PATH,
        [workspaceId, key, contentType, contentLengthFromQuery],
        expiresAt,
        token
      )
    ) {
      throw new BlobInvalid('Invalid upload token');
    }

    const record = await this.models.blob.get(workspaceId, key);
    if (!record) {
      throw new BlobInvalid('Blob upload is not initialized');
    }
    if (record.status === 'completed' || record.deletedAt) {
      throw new BlobInvalid('Blob upload is already completed');
    }

    const contentLengthHeader = this.parseContentLength(req);
    if (
      contentLengthHeader !== undefined &&
      contentLengthFromQuery !== contentLengthHeader
    ) {
      throw new BlobInvalid('Content length mismatch');
    }

    const contentLength = contentLengthHeader ?? contentLengthFromQuery;
    if (record.size && contentLength !== record.size) {
      throw new BlobInvalid('Content length does not match upload metadata');
    }

    if (record.mime && contentType && record.mime !== contentType) {
      throw new BlobInvalid('Mime type mismatch');
    }

    try {
      await this.rt.putObject(
        'blob',
        `${workspaceId}/.reservations/${record.reservationId}/${key}`,
        await toBuffer(req),
        { contentType, contentLength }
      );
    } catch (error) {
      this.logger.error('Failed to proxy upload', error as Error);
      throw new BlobInvalid('Upload failed');
    }

    res.status(200).end();
  }
